div.script:
(function(){
    var btn = document.getElementById('btn_warm_greet');
    if (btn) {
        btn.addEventListener('click', function(){
            try { window.speechSynthesis.cancel(); } catch(e) {}
            var text = '歡迎回家。這是屬於我們的社區，一起把日子過得更好。';
            var u = new SpeechSynthesisUtterance(text);
            u.lang = 'zh-TW';
            window.speechSynthesis.speak(u);
        });
    }
})();

(async function(){
    async function jsonRpc(url, params) {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: params, id: Math.floor(Math.random() * 1000) })
        });
        const result = await response.json();
        if (result.error) throw result.error;
        return result.result;
    }

    try {
        const m = await jsonRpc('/web/login/portal_map', {});
        var sel = document.getElementById('portal_select');
        var go = document.getElementById('portal_go');
        var desc = document.getElementById('portal_desc');
        function get(id){ return (m && m[id]) || null; }
        function render(){ var id = sel.value; var o = get(id); desc.textContent = o ? o.desc || '' : ''; go.href = o ? o.url || '#' : '#'; }
        if (sel) { sel.addEventListener('change', render); }
        render();
    } catch(e) { console.error('Portal map load failed', e); }
})();

(async function(){
    async function jsonRpc(url, params) {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: params, id: Math.floor(Math.random() * 1000) })
        });
        const result = await response.json();
        if (result.error) throw result.error;
        return result.result;
    }

    function setMarquee(t){
        var el = document.getElementById('marquee_text');
        if (!el) return;
        el.textContent = t || '';
        var wrap = document.getElementById('marquee_wrap');
        if (!t) { wrap.style.display = 'none'; return; }
        wrap.style.display = 'block';
        var inner = document.getElementById('marquee_inner');
        inner.style.transition = 'none';
        inner.style.transform = 'translateX(0)';
        setTimeout(function(){
            inner.style.transition = 'transform 15s linear';
            inner.style.transform = 'translateX(-50%)';
        }, 50);
    }

    try {
        const d = await jsonRpc('/wuchang/ads/marquee', {});
        var fallback = '系統我準備好了，請大家幫我測試這個為大家賺錢、為我們建設家園的系統到底好不好用。';
        var txt = (d && d.text) || fallback;
        setMarquee(txt);
    } catch(e) {
        console.error('Marquee load failed', e);
        setMarquee('系統準備中...');
    }

    try {
        const s = await jsonRpc('/wuchang/ads/login/status', {});
        var vb = document.getElementById('login_video_box');
        var ab = document.getElementById('login_audio_box');
        var v = document.getElementById('login_video');
        var a = document.getElementById('login_audio');
        if (s && s.has_video) { vb.style.display = 'block'; if (v) v.src = '/wuchang/ads/login/video'; }
        if (s && s.has_audio) { ab.style.display = 'block'; if (a) a.src = '/wuchang/ads/login/audio'; }
    } catch(e) { console.error('Status load failed', e); }
})();

xpath.script:
(async function(){

    async function jsonRpc(url, params) {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: params, id: Math.floor(Math.random() * 1000) })
        });
        const result = await response.json();
        if (result.error) throw result.error;
        return result.result;
    }

    try {
        const roles = await jsonRpc("/web/login/roles", {});
        var selectEl = document.getElementById('login_role');
        if (roles && roles.length > 0 && selectEl) {
            roles.forEach(function(role) {
                var opt = document.createElement('option');
                opt.value = role.technical_key;
                opt.textContent = role.name;
                selectEl.appendChild(opt);
            });
        } else {
            var wrap = document.querySelector('.field-login_role');
            if (wrap) { wrap.style.display = 'none'; }
        }
    } catch(e) { console.error('Roles load failed', e); }

    try {
        const providers = await jsonRpc('/web/login/oauth_providers', {});
        var box = document.getElementById('oauth_buttons');
        if (providers && providers.length && box) {
            providers.forEach(function(p) {
                var btn = document.createElement('a');
                btn.className = 'btn btn-outline-primary';
                btn.textContent = p.name;
                btn.href = '/auth_oauth/signin?provider=' + p.id;
                box.appendChild(btn);
            });
        } else {
            var field = document.querySelector('.field-oauth-providers');
            if (field) { field.style.display = 'none'; }
        }
    } catch(e) { console.error('OAuth load failed', e); }
})();

div.script:
(async function(){

    async function jsonRpc(url, params) {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: params, id: Math.floor(Math.random() * 1000) })
        });
        const result = await response.json();
        if (result.error) throw result.error;
        return result.result;
    }

    try {
        const d = await jsonRpc('/web/login/branding_info', {});
        var c = document.getElementById('brand_company');
        var o = document.getElementById('brand_organization');
        var f = document.getElementById('brand_funding');
        var p = document.getElementById('brand_phone');
        var r = document.getElementById('brand_producer');
        var a = document.getElementById('brand_association');
        var co = document.getElementById('brand_coffee_org');
        var t = document.getElementById('brand_patent');
        var pn = document.getElementById('brand_patent_no');
        if (c && d.company_name) { c.textContent = '商標與公司：' + d.company_name; }
        if (o && d.organization_info) { o.textContent = '組織身份：' + d.organization_info; }
        if (f && d.funding_source) { f.textContent = '資金來源：' + d.funding_source; }
        if (p && d.phone) { p.textContent = '客服電話：' + d.phone; }
        if (r && d.producer) { r.textContent = '製作人資訊：' + d.producer; }
        if (a && d.association) { a.textContent = '協會：' + d.association; }
        if (co && d.coffee_org) { co.innerHTML = '系統開發支持：<a href="https://www.google.com/maps/place/204,+Section+3,+Chongxin+Rd,+Sanchong+District,+New+Taipei+City/@25.0818,121.4898,15z" target="_blank" rel="noopener noreferrer">' + d.coffee_org + '</a>'; }
        if (t && d.patent) { t.textContent = '專利宣告：' + d.patent; }
        if (pn && d.patent_no) { pn.textContent = '專利字號：' + d.patent_no; }
        var mode = d && d.home_mode || '';
        if (mode === 'personal' || mode === 'coffee') {
            var assocAlert = document.querySelector('.alert.alert-dark.text-center'); if (assocAlert) assocAlert.style.display = 'none';
            var brandAssoc = document.getElementById('brand_association'); if (brandAssoc) brandAssoc.style.display = 'none';
        }
        if (mode === 'personal') {
            var hero = document.querySelector('.whc-hero'); if (hero) hero.style.display = 'none';
            var heroCap = document.querySelector('.whc-hero-caption'); if (heroCap) heroCap.style.display = 'none';
            var brandBox = document.getElementById('branding_info'); if (brandBox) brandBox.style.display = 'none';
            var vb = document.getElementById('login_video_box'); if (vb) vb.style.display = 'none';
            var ab = document.getElementById('login_audio_box'); if (ab) ab.style.display = 'none';
            var mq = document.getElementById('marquee_wrap'); if (mq) mq.style.display = 'none';
        }
    } catch(e) { console.error('Branding load failed', e); }
})();

(async function(){

    async function jsonRpc(url, params) {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: params, id: Math.floor(Math.random() * 1000) })
        });
        const result = await response.json();
        if (result.error) throw result.error;
        return result.result;
    }

    var btn = document.getElementById('btn_store_contact');
    if (btn) {
        btn.addEventListener('click', async function(e){
            e.preventDefault();
            try {
                const d = await jsonRpc('/web/login/branding_info', {});
                var lines = [];
                if (d && d.coffee_main_phone) { lines.push('重新總店：' + d.coffee_main_phone); }
                if (d && d.coffee_branch_phone) { lines.push('仁義分店：' + d.coffee_branch_phone); }
                var txt = lines.join('\n');
                window.alert(txt || '暫無門市電話');
            } catch(e) { console.error('Contact load failed', e); window.alert('載入失敗'); }
        });
    }
})();

