(function(){
    var cam = document.getElementById('cam');
    var cvs = document.getElementById('canvas');
    var f = document.getElementById('upload_form');
    var fileInput = document.getElementById('image_file');
    var stream = null;
    function start(){
        navigator.mediaDevices.getUserMedia({ video: true }).then(function(s){ stream = s; cam.srcObject = s; }).catch(function(e){ alert('無法開啟相機：'+e); });
    }
    function toBlob(){
        var w = cam.videoWidth; var h = cam.videoHeight; if (!w || !h) { alert('相機尚未就緒'); return null; }
        cvs.width = w; cvs.height = h; var ctx = cvs.getContext('2d'); ctx.drawImage(cam, 0, 0, w, h);
        return new Promise(function(resolve){ cvs.toBlob(resolve, 'image/png'); });
    }
    function upload(blob){
        var dt = new DataTransfer(); var file = new File([blob], 'capture.png', { type: 'image/png' }); dt.items.add(file); fileInput.files = dt.files; f.submit();
    }
    document.getElementById('btn_start').addEventListener('click', start);
    document.getElementById('btn_capture').addEventListener('click', function(){ toBlob().then(function(b){ if (b) upload(b); }); });
})();

(function(){
    var btn = document.getElementById('btn_save');
    var box = document.getElementById('result_box');
    function text(s){ box.innerText = s; }
    function json(v){ box.textContent = JSON.stringify(v, null, 2); }
    function save(){
        var channel_id = document.getElementById('fld_channel_id').value.trim();
        var channel_secret = document.getElementById('fld_channel_secret').value.trim();
        var callback_url = document.getElementById('fld_callback_url').value.trim();
        var provider_setup = !!document.getElementById('fld_provider_setup').checked;
        text('執行中...');
        fetch('/api/line/config', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ channel_id: channel_id, channel_secret: channel_secret, callback_url: callback_url, provider_setup: provider_setup })
        }).then(function(r){ return r.json(); }).then(function(d){ json(d); }).catch(function(e){ text(String(e)); });
    }
    if (btn) { btn.addEventListener('click', save); }
})();

(function(){
    var a = document.getElementById('agree_all');
    var b = document.getElementById('login_btn');
    function hasConsent(){
        return (document.cookie || '').split(';').some(function(x){
            return x.trim().indexOf('wuchang_consent=') === 0 && x.indexOf('true') >= 0;
        });
    }
    function setConsent(){
        try {
            document.cookie = 'wuchang_consent=true; max-age=31536000; path=/';
        } catch(e) {}
    }
    function update(){
        var ok = a && a.checked;
        if (ok) { b.classList.remove('disabled'); b.setAttribute('aria-disabled','false'); }
        else { b.classList.add('disabled'); b.setAttribute('aria-disabled','true'); }
    }
    function gate(e){
        var ok = a && a.checked;
        if (!ok) { e.preventDefault(); alert('請先勾選同意隱私政策與使用條款'); }
        else { setConsent(); }
    }
    if (a && b) {
        if (hasConsent()) { a.checked = true; }
        a.addEventListener('change', update);
        b.addEventListener('click', gate);
        update();
    }
})();

(async function(){
    async function jsonRpc(url, params) {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: params, id: Math.floor(Math.random() * 1000) })
        });
        const result = await response.json();
        if (result.error) throw result.error;
        return result.result;
    }

    var addrEl = document.getElementById('rt_addr');
    var probeBtn = document.getElementById('rt_probe');
    var statusBox = document.getElementById('rt_status');
    function renderStatus(s){
        var lines = [];
        lines.push('位址：' + (s.address || ''));
        lines.push('HTTP：' + (s.http_ok ? '可用' : '不可用'));
        lines.push('HTTPS：' + (s.https_ok ? '可用' : '不可用'));
        lines.push('Server：' + (s.server || ''));
        if (s.login_hint) { lines.push('登入頁提示：' + s.login_hint); }
        statusBox.textContent = lines.join(' | ');
    }
    async function doProbe(){
        var addr = (addrEl && addrEl.value) || '192.168.50.1';
        try {
            const s = await jsonRpc('/api/router/rt86u/probe', { address: addr });
            renderStatus(s || {});
        } catch(e) { console.error('Probe failed', e); }
    }
    if (probeBtn) { probeBtn.addEventListener('click', function(e){ e.preventDefault(); doProbe(); }); }
    setTimeout(doProbe, 200);
})();
